// Type declarations for direct @hugeicons/core-free-icons subpath imports.
// The package exposes ./* exports but only ships a single index.d.ts,
// so we declare the modules used in this project here.
// Each icon module uses `export { IconName as default }`.

type IconSvgObject = ([string, { [key: string]: string | number }])[] |
  readonly (readonly [string, { readonly [key: string]: string | number }])[];

declare module "@hugeicons/core-free-icons/ArrowDown01Icon" {
  const ArrowDown01Icon: IconSvgObject;
  export default ArrowDown01Icon;
}
